// Accept a JSON object, optionally wrapped in a code fence or surrounding prose.
const raw = String($json.output ?? '').trim();
let cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
const start = cleaned.indexOf('{');
const end = cleaned.lastIndexOf('}');
if (start >= 0 && end > start) cleaned = cleaned.slice(start, end + 1);
let tasks = [];
try {
  const data = JSON.parse(cleaned);
  if (data && !Array.isArray(data) && Array.isArray(data.tasks) && data.tasks.every(task => task && ['it', 'meeting', 'other'].includes(task.type) && typeof task.text === 'string' && task.text.trim())) {
    tasks = data.tasks.map(task => ({ type: task.type, text: task.text.trim() }));
  }
} catch (error) {
  // Malformed model output returns an empty task list.
}
const body = $('Assistant webhook').first().json.body ?? {};
const hasValue = value => typeof value === 'string' && value.trim().length > 0;
const agents = { it: 'it-agent', meeting: 'meeting-agent', other: '담당자 연결' };
tasks = tasks.map(task => {
  const missing = [];
  if (task.type === 'it' && !hasValue(body.user)) missing.push('user');
  if (task.type === 'meeting' && !hasValue(body.notes)) missing.push('notes');
  return { ...task, agent: agents[task.type], missing };
});
return [{ json: { count: tasks.length, tasks } }];
